//! Idempotent keys (design §3, §9): every task carries a stable key derived from where it came
//! from and its text, so a retry, a rerun or a crash between "sent" and "acknowledged" never
//! makes a second task. The ledger (kind `task_key`) remembers, per provider and key, the remote
//! id a create got and its state, so a task completed or deleted in the provider is not made
//! again by a rerun.
//!
//! `keys-vectors.json` (read by `tests::matches_nayas_commitment_key_byte_for_byte`) is not
//! hand-typed: it was generated by running Naya's real `normalizeCommitment`/`commitmentKey`
//! (`naya.ai/plugin/scripts/lib/todoist.mjs`) under node over a list of source/text pairs. To
//! regenerate after a change to either side's normalization, run (read-only against Naya):
//! ```sh
//! node -e '
//!   import("/path/to/naya.ai/plugin/scripts/lib/todoist.mjs").then(({ commitmentKey, normalizeCommitment }) => {
//!     const cases = [["meeting:m1:4", "I'\''ll send you the names by Friday."], /* ... */];
//!     console.log(JSON.stringify(cases.map(([source, text]) =>
//!       ({ source, text, normalized: normalizeCommitment(text), key: commitmentKey(source, text) })), null, 2));
//!   })' > src-tauri/src/workspace/task_provider/keys-vectors.json
//! ```
use crate::workspace::models::{Record, Result, WorkspaceError};
use crate::workspace::repository::Repository;
use serde_json::{json, Value};
use sha1::{Digest, Sha1};
use unicode_normalization::UnicodeNormalization;

/// Bookkeeping (kind `task_key`, id `<provider>|<key>`, unversioned, no workspace: the id is
/// already unique). Read and written by the outbox and sync job (Task 4); until then
/// `ledger_get`/`ledger_put` are exercised only by this module's own tests.
const LEDGER_KIND: &str = "task_key";

/// Naya's normalization (`normalizeCommitment` in `naya.ai/plugin/scripts/lib/todoist.mjs`):
/// `text.normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}#]+/gu, ' ').trim()` — NFKC, lower
/// case, every maximal run of characters that is *not* a letter, a digit or `#` (this includes
/// whitespace itself) collapses to exactly one space, then the result is trimmed. A disallowed
/// character is never silently dropped: it always becomes part of the run that turns into one
/// space, whether or not it sits next to whitespace (so `"well-known"` reads `"well known"`, not
/// `"wellknown"`, matching Naya byte-for-byte — see `keys-vectors.json`, generated from the real
/// `normalizeCommitment`/`commitmentKey`).
pub(crate) fn normalize(text: &str) -> String {
    let folded: String = text.nfkc().collect::<String>().to_lowercase();
    let mut out = String::with_capacity(folded.len());
    let mut pending_space = false;
    for ch in folded.chars() {
        if ch.is_alphanumeric() || ch == '#' {
            if pending_space {
                out.push(' ');
                pending_space = false;
            }
            out.push(ch);
        } else {
            // Any other character — punctuation, dashes, emoji, or plain whitespace — joins the
            // same run and becomes (at most) one space, never a silent drop.
            pending_space = !out.is_empty();
        }
    }
    out
}

/// `sha1("<source>#<normalized text>")`, the first 16 hex characters (design §3, §9).
pub(crate) fn task_key(source: &str, text: &str) -> String {
    let input = format!("{source}#{}", normalize(text));
    let digest = Sha1::digest(input.as_bytes());
    digest.iter().take(8).map(|b| format!("{b:02x}")).collect()
}

#[allow(dead_code)] // called by ledger_get/ledger_put, which the outbox and sync job (Task 4) use
fn ledger_id(provider: &str, key: &str) -> String {
    format!("{provider}|{key}")
}

/// The ledger entry for `provider`'s `key` (`{remoteId, state, at}`), or `None` when the key was
/// never created for that provider.
#[allow(dead_code)] // the outbox and sync job (Task 4) check the ledger before a create
pub(crate) fn ledger_get(r: &Repository, provider: &str, key: &str) -> Result<Option<Value>> {
    match r.record(LEDGER_KIND, &ledger_id(provider, key), None, None) {
        Ok(record) => Ok(Some(record.data)),
        Err(WorkspaceError { code, .. }) if code == "not_found" => Ok(None),
        Err(e) => Err(e),
    }
}

/// Remembers `key`'s outcome with `provider`: `state` is `created`, `done`, `withdrawn` or
/// `removed` (design §3); `remote_id` is the provider's task id, when there is one.
#[allow(dead_code)] // the outbox and sync job (Task 4) record a create's remote id this way
pub(crate) fn ledger_put(
    r: &mut Repository,
    provider: &str,
    key: &str,
    remote_id: Option<&str>,
    state: &str,
    now: i64,
) -> Result<()> {
    r.put_record_unversioned(&Record {
        id: ledger_id(provider, key),
        kind: LEDGER_KIND.into(),
        connection_id: None,
        workspace_id: None,
        source: "local".into(),
        revision: crate::workspace::models::id(),
        updated_at: now,
        data: json!({"remoteId": remote_id, "state": state, "at": now}),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::workspace::test_core;

    #[test]
    fn task_key_matches_nayas_normalization() {
        let a = task_key("meeting:m1:4", "I'll send you the names by Friday.");
        let b = task_key("meeting:m1:4", "  i'll SEND you the names, by friday ");
        assert_eq!(
            a, b,
            "same source and the same text, differently cased and punctuated"
        );
        assert_eq!(a.len(), 16);
        assert!(a.chars().all(|c| c.is_ascii_hexdigit()), "{a}");
        let c = task_key("message:m-1", "I'll send you the names by Friday.");
        assert_ne!(a, c, "another source gives another key");
        assert_eq!(normalize("Ёлка — #2!"), "ёлка #2");
    }

    /// A disallowed character (punctuation, an apostrophe, a dash) must collapse into the
    /// surrounding run and become a single space — never be silently dropped, which would merge
    /// two words and let distinct texts collide on the same key.
    #[test]
    fn normalize_collapses_unspaced_punctuation_instead_of_dropping_it() {
        assert_eq!(normalize("well-known issue"), "well known issue");
        assert_eq!(
            normalize("I'll send you the names by Friday."),
            "i ll send you the names by friday"
        );
        assert_eq!(normalize("foo/bar"), "foo bar");
        assert_eq!(normalize("end.of.sentence"), "end of sentence");
        // Two texts that differ only in whether the separator is punctuation or a space still
        // fold together; a text with no separator at all is, correctly, a different key.
        assert_eq!(normalize("well-known issue"), normalize("well known issue"));
        assert_ne!(normalize("well-known issue"), normalize("wellknown issue"));
    }

    /// Byte-for-byte parity with Naya's real `normalizeCommitment`/`commitmentKey`
    /// (`naya.ai/plugin/scripts/lib/todoist.mjs`), over vectors covering punctuation,
    /// apostrophes, em dashes, emoji, Cyrillic, mixed case, leading/trailing marks and `#`
    /// suffixes. `keys-vectors.json` was generated by running that real JS function with node,
    /// not hand-typed — see its generation note below.
    #[test]
    fn matches_nayas_commitment_key_byte_for_byte() {
        #[derive(serde::Deserialize)]
        struct Vector {
            source: String,
            text: String,
            normalized: String,
            key: String,
        }
        let vectors: Vec<Vector> =
            serde_json::from_str(include_str!("keys-vectors.json")).expect("valid vectors JSON");
        assert!(
            vectors.len() >= 10,
            "need at least 10 cross-implementation vectors, got {}",
            vectors.len()
        );
        for v in &vectors {
            assert_eq!(
                normalize(&v.text),
                v.normalized,
                "normalize({:?}) should match Naya's normalizeCommitment",
                v.text
            );
            assert_eq!(
                task_key(&v.source, &v.text),
                v.key,
                "task_key({:?}, {:?}) should match Naya's commitmentKey",
                v.source,
                v.text
            );
        }
    }

    #[test]
    fn ledger_remembers_a_keys_outcome_per_provider() {
        let dir = tempfile::tempdir().unwrap();
        let core = test_core(
            dir.path(),
            std::sync::Arc::new(crate::ai::fake::FakeRunner::new(vec![])),
            crate::workspace::ai::tests::ready(),
        );
        let mut r = core.repo().unwrap();
        assert_eq!(ledger_get(&r, "plugin:todoist", "abc123").unwrap(), None);
        ledger_put(
            &mut r,
            "plugin:todoist",
            "abc123",
            Some("8124"),
            "created",
            1_795_000_000,
        )
        .unwrap();
        let entry = ledger_get(&r, "plugin:todoist", "abc123").unwrap().unwrap();
        assert_eq!(entry["remoteId"], "8124");
        assert_eq!(entry["state"], "created");
        // Another provider's ledger for the same key is separate.
        assert_eq!(ledger_get(&r, "local", "abc123").unwrap(), None);
    }
}
